import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls';

class VWBuzzConfigurator {
  private scene: THREE.Scene;
  private camera: THREE.PerspectiveCamera;
  private renderer: THREE.WebGLRenderer;
  private controls: OrbitControls;
  private vehicleModel: THREE.Group;
  private materials: Map<string, THREE.MeshStandardMaterial>;

  constructor(canvas: HTMLCanvasElement) {
    this.scene = new THREE.Scene();
    this.scene.background = new THREE.Color(0xf0f0f0);

    this.camera = new THREE.PerspectiveCamera(
      45,
      window.innerWidth / window.innerHeight,
      0.1,
      1000
    );
    this.camera.position.set(5, 2, 5);

    this.renderer = new THREE.WebGLRenderer({
      canvas,
      antialias: true,
      alpha: true
    });
    this.renderer.setSize(window.innerWidth, window.innerHeight);
    this.renderer.setPixelRatio(window.devicePixelRatio);
    this.renderer.toneMapping = THREE.ACESFilmicToneMapping;
    this.renderer.toneMappingExposure = 1;
    this.renderer.outputEncoding = THREE.sRGBEncoding;

    this.controls = new OrbitControls(this.camera, this.renderer.domElement);
    this.controls.enableDamping = true;
    this.controls.dampingFactor = 0.05;
    this.controls.minDistance = 3;
    this.controls.maxDistance = 10;

    this.setupLighting();
    this.materials = new Map();
  }

  private setupLighting(): void {
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
    this.scene.add(ambientLight);

    const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
    directionalLight.position.set(5, 10, 5);
    directionalLight.castShadow = true;
    directionalLight.shadow.mapSize.width = 2048;
    directionalLight.shadow.mapSize.height = 2048;
    this.scene.add(directionalLight);

    const hemisphereLight = new THREE.HemisphereLight(0xffffff, 0x444444, 0.6);
    this.scene.add(hemisphereLight);
  }

  async loadVehicle(modelUrl: string): Promise<void> {
    const loader = new GLTFLoader();

    return new Promise((resolve, reject) => {
      loader.load(
        modelUrl,
        (gltf) => {
          this.vehicleModel = gltf.scene;
          this.vehicleModel.position.set(0, 0, 0);
          this.vehicleModel.traverse((child) => {
            if ((child as THREE.Mesh).isMesh) {
              const mesh = child as THREE.Mesh;
              mesh.castShadow = true;
              mesh.receiveShadow = true;

              if (mesh.material) {
                const material = mesh.material as THREE.MeshStandardMaterial;
                this.materials.set(mesh.name, material);
              }
            }
          });

          this.scene.add(this.vehicleModel);
          resolve();
        },
        (progress) => {
          console.log(`Loading: ${(progress.loaded / progress.total * 100).toFixed(2)}%`);
        },
        reject
      );
    });
  }

  applyWrapTexture(textureUrl: string, targetParts: string[]): void {
    const textureLoader = new THREE.TextureLoader();
    textureLoader.load(textureUrl, (texture) => {
      texture.encoding = THREE.sRGBEncoding;
      texture.flipY = false;

      targetParts.forEach(partName => {
        const material = this.materials.get(partName);
        if (material) {
          material.map = texture;
          material.needsUpdate = true;
        }
      });
    });
  }

  animate = (): void => {
    requestAnimationFrame(this.animate);
    this.controls.update();
    this.renderer.render(this.scene, this.camera);
  };
}

import React, { useEffect, useRef, useState } from 'react';
import { VWBuzzConfigurator } from './VWBuzzConfigurator';

interface ConfiguratorProps {
  modelUrl: string;
  onReady?: () => void;
}

export const BuzzConfigurator: React.FC<ConfiguratorProps> = ({
  modelUrl,
  onReady
}) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const configuratorRef = useRef<VWBuzzConfigurator>();
  const [selectedWrap, setSelectedWrap] = useState<string | null>(null);
  const [selectedColor, setSelectedColor] = useState('#ffffff');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (!canvasRef.current) return;

    const configurator = new VWBuzzConfigurator(canvasRef.current);
    configuratorRef.current = configurator;

    configurator.loadVehicle(modelUrl).then(() => {
      setLoading(false);
      onReady?.();
      configurator.animate();
    });

    const handleResize = () => {
      configurator.resize(window.innerWidth, window.innerHeight);
    };
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      configurator.dispose();
    };
  }, [modelUrl, onReady]);

  const handleWrapChange = (wrapId: string) => {
    setSelectedWrap(wrapId);
    if (configuratorRef.current) {
      const textureUrl = `/textures/wraps/${wrapId}.jpg`;
      configuratorRef.current.applyWrapTexture(textureUrl, [
        'body_panel_left',
        'body_panel_right',
        'door_left',
        'door_right'
      ]);
    }
  };

  const handleColorChange = (color: string) => {
    setSelectedColor(color);
    if (configuratorRef.current) {
      configuratorRef.current.setBaseColor(color);
    }
  };

  const handleExport = async () => {
    if (!configuratorRef.current) return;

    const screenshot = await configuratorRef.current.captureScreenshot();
    const config = {
      wrap: selectedWrap,
      color: selectedColor,
      timestamp: new Date().toISOString()
    };

    const response = await fetch('/api/orders', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ screenshot, config })
    });

    if (response.ok) {
      window.location.href = '/order/confirmation';
    }
  };

  return (
    <div className="configurator-container">
      {loading && (
        <div className="loading-overlay">
          <div className="spinner" />
          <p>Loading 3D Model...</p>
        </div>
      )}
      <canvas ref={canvasRef} className="configurator-canvas" />
      <div className="controls-panel">
        <WrapSelector 
          selected={selectedWrap} 
          onChange={handleWrapChange} 
        />
        <ColorPicker 
          color={selectedColor} 
          onChange={handleColorChange} 
        />
        <button 
          className="btn-export" 
          onClick={handleExport}
          disabled={!selectedWrap}
        >
          Order Custom Wrap
        </button>
      </div>
    </div>
  );
};

