class MaterialManager {
  private materials: Map<string, THREE.Material>;
  private textureCache: Map<string, THREE.Texture>;

  constructor() {
    this.materials = new Map();
    this.textureCache = new Map();
  }

  createCarPaintMaterial(color: string): THREE.MeshStandardMaterial {
    return new THREE.MeshStandardMaterial({
      color: new THREE.Color(color),
      metalness: 0.8,
      roughness: 0.2,
      envMapIntensity: 1.5,
      clearcoat: 1.0,
      clearcoatRoughness: 0.1
    });
  }

  async loadWrapMaterial(textureUrl: string): Promise<THREE.MeshStandardMaterial> {
    let texture = this.textureCache.get(textureUrl);

    if (!texture) {
      texture = await this.loadTexture(textureUrl);
      this.textureCache.set(textureUrl, texture);
    }

    return new THREE.MeshStandardMaterial({
      map: texture,
      metalness: 0.3,
      roughness: 0.7,
      normalScale: new THREE.Vector2(1, 1)
    });
  }

  private loadTexture(url: string): Promise<THREE.Texture> {
    return new Promise((resolve, reject) => {
      const loader = new THREE.TextureLoader();
      loader.load(
        url,
        (texture) => {
          texture.encoding = THREE.sRGBEncoding;
          texture.flipY = false;
          texture.wrapS = THREE.RepeatWrapping;
          texture.wrapT = THREE.RepeatWrapping;
          resolve(texture);
        },
        undefined,
        reject
      );
    });
  }

  dispose(): void {
    this.materials.forEach(material => material.dispose());
    this.textureCache.forEach(texture => texture.dispose());
    this.materials.clear();
    this.textureCache.clear();
  }
}

class CameraController {
  private camera: THREE.PerspectiveCamera;
  private controls: OrbitControls;
  private presets: Map<string, CameraPreset>;

  constructor(
    camera: THREE.PerspectiveCamera,
    domElement: HTMLElement
  ) {
    this.camera = camera;
    this.controls = new OrbitControls(camera, domElement);
    this.setupControls();
    this.definePresets();
  }

  private setupControls(): void {
    this.controls.enableDamping = true;
    this.controls.dampingFactor = 0.05;
    this.controls.screenSpacePanning = false;
    this.controls.minDistance = 3;
    this.controls.maxDistance = 10;
    this.controls.maxPolarAngle = Math.PI / 2;
  }

  private definePresets(): void {
    this.presets = new Map([
      ['front', {
        position: new THREE.Vector3(0, 1.5, 5),
        target: new THREE.Vector3(0, 1, 0)
      }],
      ['side', {
        position: new THREE.Vector3(5, 1.5, 0),
        target: new THREE.Vector3(0, 1, 0)
      }],
      ['rear', {
        position: new THREE.Vector3(0, 1.5, -5),
        target: new THREE.Vector3(0, 1, 0)
      }],
      ['top', {
        position: new THREE.Vector3(0, 8, 0.1),
        target: new THREE.Vector3(0, 0, 0)
      }]
    ]);
  }

  animateToPreset(presetName: string, duration: number = 1000): Promise<void> {
    const preset = this.presets.get(presetName);
    if (!preset) return Promise.reject('Preset not found');

    return new Promise((resolve) => {
      const startPosition = this.camera.position.clone();
      const startTarget = this.controls.target.clone();
      const startTime = Date.now();

      const animate = () => {
        const elapsed = Date.now() - startTime;
        const progress = Math.min(elapsed / duration, 1);
        const eased = this.easeInOutCubic(progress);

        this.camera.position.lerpVectors(
          startPosition,
          preset.position,
          eased
        );
        this.controls.target.lerpVectors(
          startTarget,
          preset.target,
          eased
        );

        this.controls.update();

        if (progress < 1) {
          requestAnimationFrame(animate);
        } else {
          resolve();
        }
      };

      animate();
    });
  }

  private easeInOutCubic(t: number): number {
    return t < 0.5
      ? 4 * t * t * t
      : 1 - Math.pow(-2 * t + 2, 3) / 2;
  }
}

